<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
html, body { background: transparent !important; width: 100%; }
body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'PingFang SC', 'Microsoft YaHei', sans-serif; line-height: 1.45; padding: 2px 0; }
.ao-card {
  position: relative;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 12px;
  padding: 8px 0 6px;
  background: #181a1f;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.35);
}
.ao-mode-btn {
  position: absolute;
  top: 7px;
  right: 9px;
  z-index: 5;
  background: rgba(255, 255, 255, 0.10);
  color: #ffffff;
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 8px;
  font-size: 12px;
  line-height: 1;
  padding: 4px 10px;
  cursor: pointer;
  transition: background 0.15s ease;
}
.ao-mode-btn:hover { background: rgba(255, 255, 255, 0.20); }
.ao-mode-btn.mode-send { background: rgba(120, 180, 255, 0.25); border-color: rgba(120, 180, 255, 0.45); }
.ao-line {
  display: block;
  width: 100%;
  text-align: left;
  color: #ffffff;
  font-size: 14px;
  padding: 9px 14px;
  cursor: pointer;
  white-space: pre-wrap;
  word-break: break-word;
  user-select: text;
  -webkit-user-select: text;
  -webkit-touch-callout: default;
}
.ao-line:first-child { padding-right: 72px; }
.ao-line + .ao-line { border-top: 1px dashed rgba(255, 255, 255, 0.18); }
.ao-line.active { background: rgba(255, 255, 255, 0.10); }
.ao-empty {
  font-size: 13px;
  color: rgba(255, 255, 255, 0.6);
  padding: 10px 14px;
}
</style>
</head>
<body>
<div class="ao-card" id="aoCard">
  <button type="button" class="ao-mode-btn" id="aoModeBtn">填入</button>
  <div id="aoLines"></div>
</div>
<script>
(function () {
  var mode = false;
  function getTopWin() {
    try {
      var w = window;
      while (w.parent && w.parent !== w) w = w.parent;
      return w;
    } catch (e) { return window; }
  }
  function getTopDoc() {
    try { return getTopWin().document; } catch (e) { return document; }
  }
  function loadMode() {
    try { return getTopWin().localStorage.getItem('ao_send_mode') === '1'; } catch (e) { return false; }
  }
  function saveMode(v) {
    try { getTopWin().localStorage.setItem('ao_send_mode', v ? '1' : '0'); } catch (e) {}
  }
  function getParentInput() {
    var topDoc = getTopDoc();
    var sels = ['#send_textarea', 'textarea[placeholder*="发送"]', 'textarea'];
    for (var i = 0; i < sels.length; i++) {
      var el = topDoc.querySelector(sels[i]);
      if (el) return el;
    }
    return null;
  }
  function stripPrefix(line) {
    return String(line).trim().replace(/^【[^】]*】\s*/, '').trim();
  }
  function fillInput(text) {
    var ta = getParentInput();
    if (!ta) { console.warn('[行动选项] 未找到主窗口输入框'); return; }
    ta.value = text;
    ta.dispatchEvent(new Event('input', { bubbles: true }));
    ta.focus();
  }
  function sendNow() {
    var b = getTopDoc().querySelector('#send_but');
    if (b) b.click(); else console.warn('[行动选项] 未找到发送按钮');
  }
  function updateBtn() {
    var btn = document.getElementById('aoModeBtn');
    if (!btn) return;
    btn.textContent = mode ? '发送' : '填入';
    btn.title = mode ? '当前：点击选项直接发送（点击切换为填入）' : '当前：点击选项填入输入框（点击切换为直接发送）';
    btn.classList.toggle('mode-send', mode);
  }
  function attachLine(line) {
    var el = document.createElement('div');
    el.className = 'ao-line';
    el.textContent = line;
    el.addEventListener('mousedown', function () { el.classList.add('active'); });
    el.addEventListener('mouseup', function () { el.classList.remove('active'); });
    el.addEventListener('mouseleave', function () { el.classList.remove('active'); });
    el.addEventListener('click', function (e) {
      var sel = '';
      try { sel = window.getSelection().toString(); } catch (err) {}
      if (sel) return;
      fillInput(stripPrefix(line));
      if (mode) sendNow();
    });
    return el;
  }
  function render(lines) {
    var box = document.getElementById('aoLines');
    if (!box) return;
    box.innerHTML = '';
    if (!lines || !lines.length) {
      var empty = document.createElement('div');
      empty.className = 'ao-empty';
      empty.textContent = '行动选项暂未加载';
      box.appendChild(empty);
      return;
    }
    lines.forEach(function (line) { box.appendChild(attachLine(line)); });
  }
  function extract(raw) {
    var m = null, re = /^[ \t]*<选项>([\s\S]*?)<\/选项>/gim, last = null;
    var src = (raw || '').replace(/<思考>[\s\S]*?<\/思考>/gi, '');
    while ((m = re.exec(src)) !== null) last = m;
    if (!last) return null;
    return last[1].split('\n').map(function (s) { return s.trim(); }).filter(function (s) { return s.length > 0; });
  }
  function init() {
    mode = loadMode();
    var btn = document.getElementById('aoModeBtn');
    if (btn) {
      btn.addEventListener('click', function () {
        mode = !mode;
        saveMode(mode);
        updateBtn();
      });
    }
    updateBtn();
    var lines = null;
    try {
      if (typeof getChatMessages === 'function' && typeof getCurrentMessageId === 'function') {
        var msgs = getChatMessages(getCurrentMessageId());
        if (msgs && msgs.length > 0) {
          lines = extract(msgs[0].message);
        }
      }
    } catch (e) {
      console.warn('[行动选项] 解析失败', e);
    }
    if (!lines) {
      try {
        var bodyText = document.body.innerText || '';
        lines = extract(bodyText);
      } catch (e) {}
    }
    render(lines);
  }
  if (document.readyState === 'loading') {
    window.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
</script>
</body>
</html>
